style.css:
@-moz-document url("http://produktion.sog.sanner/bestellungen/index.html"), url("http://produktion.sog.sanner/bestellungen/index.php"), url-prefix("http://produktion.sog.sanner/bestellungen/") {
/* Tło i typografia */
  html, body {
    background: linear-gradient(135deg, #1f2937, #0d1b2a) !important;
    color: #f8fafc !important;
    font-family: "Segoe UI", Roboto, Arial, sans-serif !important;
    font-size: 15px !important;
    margin: 16px !important;
  }

  /* Frameset i pasek górny */
  frameset, frame {
    background: #0d1b2a !important;
    border: 0 !important;
  }
  body::before, frameset::before {
    content: "";
    display: block;
    height: 5px;
    background: linear-gradient(90deg, #ff7b00, #f9c80e, #00ffcc) !important;
    box-shadow: 0 0 10px rgba(255, 200, 50, 0.8);
  }

  /* Tabele */
  table {
    width: 100% !important;
    border-collapse: collapse !important;
    margin: 20px 0 !important;
    border: 2px solid #00ffcc !important;
    border-radius: 12px !important;
    overflow: hidden !important;
    background: #1c2541 !important;
    box-shadow: 0 8px 20px rgba(0, 255, 204, 0.4) !important;
  }

  td {
    padding: 12px 14px !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
  }

  /* Nagłówki tabel */
  table > tbody > tr:first-child td,
  table > tr:first-child td {
    background: linear-gradient(90deg, #00ffcc, #ff7b00) !important;
    color: #0d1b2a !important;
    font-weight: 800 !important;
    text-transform: uppercase !important;
    letter-spacing: .06em !important;
    font-size: 15px !important;
    text-shadow: 0 0 5px rgba(255, 255, 255, 0.7);
  }

  /* Kolory statusów */
  tr[bgcolor="#DF01D7"] td {
    background: linear-gradient(135deg, #ff1493, #ff77ff) !important;
    color: #fff !important;
    font-weight: bold !important;
  }

  tr[bgcolor="#A9D0F5"] td {
    background: linear-gradient(135deg, #007bff, #00bfff) !important;
    color: #fff !important;
    font-weight: bold !important;
  }

  tr[bgcolor="#BCF5A9"] td {
    background: linear-gradient(135deg, #00ff7f, #00cc44) !important;
    color: #0d1b2a !important;
    font-weight: bold !important;
  }

  /* Linki akcji */
  td a[href*="view.php"] {
    display: inline-block !important;
    padding: 6px 14px !important;
    background: linear-gradient(135deg, #ff7b00, #f9c80e) !important;
    color: #0d1b2a !important;
    text-decoration: none !important;
    font-weight: bold !important;
    border-radius: 8px !important;
    box-shadow: 0 2px 8px rgba(255, 123, 0, 0.5) !important;
    transition: transform 0.1s ease, box-shadow 0.2s ease !important;
  }
  td a[href*="view.php"]:hover {
    transform: translateY(-2px) !important;
    box-shadow: 0 4px 12px rgba(255, 123, 0, 0.7) !important;
  }

  /* Hover na wierszach */
  tr:hover td {
    background: rgba(0, 255, 204, 0.15) !important;
    transition: background 0.2s ease-in-out;
  }

  /* Linie i legenda */
  hr {
    border: 0 !important;
    height: 3px !important;
    background: linear-gradient(90deg, #ff7b00, #f9c80e, #00ffcc) !important;
    box-shadow: 0 0 8px rgba(255, 200, 50, 0.7);
    margin: 20px 0 !important;
  }

  table:last-of-type td {
    font-size: 13px !important;
    color: #f8fafc !important;
  }
}
